{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Modern Wellness Blueprint</title>
  <meta name="description" content="A practical, outcomes-focused approach to habits, clarity, and steady momentum — tailored VIP Day and short programs.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="page-root">
  <header class="site-header">
    <div class="container nav-wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="main-nav">
        <a href="/about.html">Blueprint</a>
        <a href="/programs.html">Assess</a>
        <a href="/services.html">Programs</a>
        <a href="/testimonials.html">Stories</a>
        <a href="/pricing.html">Invest</a>
        <a href="/book.html">Book</a>
        <a href="/contact.html">Contact</a>
      </nav>
      <a class="cta-pill" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section id="hero" class="hero" role="region" aria-label="Hero">
      <div class="container hero-grid">
        <div class="hero-copy">
          <h1 class="title">A concise path to steadier energy and sustainable routines</h1>
          <p class="lead">Short, strategic sessions that map out the next 30 days so you can move from overwhelm to a clear, testable rhythm.</p>
          <div class="hero-actions">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">Start your 30-day map</a>
            <a class="btn ghost" href="/programs.html">See programs</a>
          </div>
          <ul class="contact-line">
            <li><strong>Call</strong> <a href="tel:{{PHONE}}">{{PHONE}}</a></li>
            <li><strong>Email</strong> <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></li>
          </ul>
        </div>
        <div class="hero-visual">
          <div class="pattern-wrap">
            <img src="assets/img/pattern.svg" alt="subtle pattern" aria-hidden="true">
          </div>
          <div class="proof-mini" aria-hidden="false">
            <div id="badge-rotator" class="badges">
              <!-- Badges rotated by JS -->
              <div class="badge" data-tip="Featured in Modern Wellness">MW</div>
              <div class="badge" data-tip="Trusted by executives">Exec</div>
              <div class="badge" data-tip="Press mention: Life+Work">L+W</div>
            </div>
            <div class="mini-testimonial">
              <blockquote id="mini-testimonial">"A sharp day that gave me a reliable week-by-week guide."</blockquote>
            </div>
          </div>
        </div>
      </div>
    </section>

    <!-- DIAGNOSTIC -->
    <section id="diagnostic" class="pane diagnostic" aria-label="Quick diagnostic">
      <div class="container">
        <h2>Quick Diagnostic: pick up to 3 goals</h2>
        <p class="muted">Select the areas you want measurable progress on in the next 30 days. We'll build a tailored path map.</p>
        <form id="goals-form" class="goals-form" aria-describedby="goals-help">
          <div id="goals-help" class="sr-only">Choose goals to shape your 30-day path</div>
          <label><input type="checkbox" name="goal" value="energy"> Improve consistent energy</label>
          <label><input type="checkbox" name="goal" value="sleep"> Better sleep timing</label>
          <label><input type="checkbox" name="goal" value="focus"> Sharpen daily focus windows</label>
          <label><input type="checkbox" name="goal" value="movement"> Daily gentle movement</label>
          <label><input type="checkbox" name="goal" value="stress"> Manage reactivity & stress</label>
          <div class="form-actions">
            <button id="build-path" class="btn primary" type="button">Map my 30 days</button>
            <button id="clear-goals" class="btn ghost" type="button">Reset</button>
          </div>
        </form>
      </div>
    </section>

    <!-- PLAN (Path map + Proof Gallery) -->
    <section id="plan" class="pane plan" aria-label="30 day plan">
      <div class="container">
        <div class="plan-head">
          <h2>Your 30-day path map</h2>
          <p class="muted">A visual rhythm and weekly milestones you can try and adjust.</p>
        </div>

        <div class="map-grid">
          <div class="map-visual" id="map-visual" aria-hidden="false">
            <!-- SVG path will be injected here -->
            <svg id="path-svg" viewBox="0 0 1000 240" preserveAspectRatio="xMidYMid meet"></svg>
          </div>
          <aside class="map-controls">
            <div class="progress-meter">
              <label>Path readiness</label>
              <div class="meter" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0">
                <div class="meter-fill" style="width:0%"></div>
              </div>
              <div id="meter-text" class="meter-text">0% ready</div>
            </div>

            <div class="proof-gallery">
              <h3>Proof & credibility</h3>
              <div id="testimonials" class="testimonials">
                <!-- Rotating testimonials -->
                <article class="testimonial active" data-author="A. Morgan" data-role="Founder">"The 1-day intensive gave me an actionable weekly layout I still use."</article>
                <article class="testimonial" data-author="S. Patel" data-role="Team Lead">"Practical shifts I could test in a single week."</article>
                <article class="testimonial" data-author="R. Kim" data-role="Designer">"Small, consistent moves that stacked into change."</article>
              </div>
              <div class="badges-list">
                <span class="cred" data-tip="Accredited coach network">AC</span>
                <span class="cred" data-tip="Enterprise clients">EC</span>
                <span class="cred" data-tip="Featured case study">CS</span>
              </div>
            </div>
          </aside>
        </div>

      </div>
    </section>

    <!-- MICRO HABITS -->
    <section id="micro_habits" class="pane micro" aria-label="Micro habits">
      <div class="container">
        <h2>Micro habits to test this week</h2>
        <p class="muted">Choose small, measurable moves. Toggled items will be reflected in your 30-day map.</p>
        <ul id="micro-list" class="micro-list">
          <li><label><input type="checkbox" data-habit="10-min-move"> 10 minutes gentle movement after lunch</label></li>
          <li><label><input type="checkbox" data-habit="pre-bed-routine"> 20-minute unwind routine before bed</label></li>
          <li><label><input type="checkbox" data-habit="focus-block"> 60-minute focused work block each morning</label></li>
          <li><label><input type="checkbox" data-habit="midday-walk"> 15-minute midday walk</label></li>
        </ul>
        <div class="micro-actions">
          <button id="apply-habits" class="btn primary" type="button">Apply selected habits</button>
        </div>
      </div>
    </section>

    <!-- PRICING -->
    <section id="pricing" class="pane pricing" aria-label="Pricing">
      <div class="container">
        <h2>Offerings</h2>
        <p class="muted">Focused engagements organized around a VIP Day and short pilots to create directional results.</p>
        <div class="pricing-grid">
          <div class="card">
            <h3>VIP Day</h3>
            <p class="price">One focused, strategy-to-plan day</p>
            <ul>
              <li>Pre-work assessment</li>
              <li>6-hour mapping session</li>
              <li>30-day path + accountability plan</li>
            </ul>
            <div class="card-footer"><a class="btn primary" href="/book.html">Book a VIP Day</a></div>
          </div>
          <div class="card">
            <h3>4-Week Pilot</h3>
            <p class="price">A short trial to validate changes</p>
            <ul>
              <li>Weekly check-ins</li>
              <li>Badge of progress & adjustments</li>
              <li>Custom micro habit pack</li>
            </ul>
            <div class="card-footer"><a class="btn ghost" href="/pricing.html">Explore pricing</a></div>
          </div>
          <div class="card">
            <h3>Team Workshop</h3>
            <p class="price">For teams building shared rhythms</p>
            <ul>
              <li>Half-day workshop</li>
              <li>Shared micro-habit framework</li>
              <li>Follow-up roadmap</li>
            </ul>
            <div class="card-footer"><a class="btn ghost" href="/services.html">See details</a></div>
          </div>
        </div>
      </div>
    </section>

    <!-- CTA -->
    <section id="cta" class="pane cta" aria-label="Call to action">
      <div class="container">
        <h2>Ready to try a focused day?</h2>
        <p class="muted">Book a VIP Day and leave with a live, editable 30-day path you can test immediately.</p>
        <div class="cta-actions">
          <a class="btn primary" href="/book.html">Reserve a VIP Day</a>
          <a class="btn ghost" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        </div>
        <p class="disclaimer">Outcomes, habits, and frameworks only. No medical claims.</p>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="container footer-grid">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <address>{{CITY}}, {{STATE}} • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></address>
      </div>
      <nav class="footer-nav">
        <a href="/about.html">About</a>
        <a href="/programs.html">Programs</a>
        <a href="/pricing.html">Pricing</a>
        <a href="/contact.html">Contact</a>
      </nav>
    </div>
  </footer>

  <script src="assets/js/main.js" defer></script>
</body>
</html>"} 
