{"path":"assets/css/styles.css","content":"/* Core styles for the wellness coach template */
:root{
  --bg:#fbfbfb;
  --card:#ffffff;
  --muted:#6b7280;
  --accent:#2b6cb0;
  --accent-2:#7c3aed;
  --text:#0f172a;
  --radius:12px;
  --glass: rgba(255,255,255,0.6);
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:var(--text);background:var(--bg);-webkit-font-smoothing:antialiased}
.container{max-width:1100px;margin:0 auto;padding:28px}
.site-header{background:linear-gradient(180deg,rgba(255,255,255,0.6),transparent);backdrop-filter: blur(6px);position:sticky;top:0;z-index:40;border-bottom:1px solid #eee}
.nav-wrap{display:flex;align-items:center;gap:16px}
.brand{font-weight:700;color:var(--text);text-decoration:none;font-size:1.05rem}
.main-nav{display:flex;gap:12px;margin-left:18px}
.main-nav a{color:var(--muted);text-decoration:none;font-size:0.95rem}
.cta-pill{margin-left:auto;background:var(--accent);color:#fff;padding:8px 12px;border-radius:999px;text-decoration:none}
.hero{padding:48px 0;background:linear-gradient(90deg,#fff,#f7fbff)}
.hero-grid{display:grid;grid-template-columns:1fr 360px;gap:28px;align-items:center}
.title{font-size:1.8rem;margin:0 0 8px}
.lead{color:var(--muted);margin:0 0 18px}
.hero-actions{display:flex;gap:10px;margin-top:12px}
.btn{display:inline-block;padding:10px 14px;border-radius:10px;text-decoration:none;font-weight:600}
.btn.primary{background:var(--accent);color:#fff}
.btn.ghost{background:transparent;border:1px solid #ddd;color:var(--text)}
.contact-line{list-style:none;padding:0;margin:16px 0 0;display:flex;gap:12px;color:var(--muted)}
.hero-visual{position:relative}
.pattern-wrap{background:linear-gradient(180deg,rgba(124,58,237,0.06),transparent);border-radius:16px;padding:18px}
.pattern-wrap img{width:100%;height:auto;display:block}
.proof-mini{margin-top:14px;display:flex;align-items:center;gap:12px}
.badges{display:flex;gap:8px}
.badge{width:42px;height:42px;border-radius:8px;background:#fff;display:flex;align-items:center;justify-content:center;border:1px solid #eee;cursor:default}
.mini-testimonial blockquote{margin:0;font-size:0.93rem;color:var(--muted)}
.pane{padding:36px 0}
.diagnostic label{display:inline-flex;align-items:center;gap:8px;background:var(--card);padding:10px;border-radius:8px;margin-right:8px;border:1px solid #f0f0f0}
.goals-form{margin-top:14px}
.form-actions{margin-top:12px}
.map-grid{display:grid;grid-template-columns:1fr 320px;gap:20px;align-items:start}
.map-visual{background:linear-gradient(180deg,#fff,#fbfdff);padding:18px;border-radius:12px;border:1px solid #eee}
.map-controls{background:var(--card);padding:18px;border-radius:12px;border:1px solid #f3f4f6}
.progress-meter label{font-weight:600}
.meter{height:16px;background:#eef2ff;border-radius:999px;margin-top:8px;overflow:hidden}
.meter-fill{height:100%;background:linear-gradient(90deg,var(--accent),var(--accent-2));width:0%;transition:width 600ms ease}
.meter-text{font-size:0.9rem;color:var(--muted);margin-top:8px}
.testimonials{margin-top:14px}
.testimonial{display:none;font-style:italic;color:var(--muted)}
.testimonial.active{display:block}
.badges-list{display:flex;gap:8px;margin-top:12px}
.cred{width:36px;height:36px;border-radius:8px;background:#fff;display:inline-flex;align-items:center;justify-content:center;border:1px solid #eee;cursor:default}
.micro-list{list-style:none;padding:0;margin:12px 0;display:grid;gap:8px}
.micro-list li{background:var(--card);padding:10px;border-radius:8px;border:1px solid #f0f0f0}
.pricing-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:12px}
.card{background:var(--card);padding:18px;border-radius:12px;border:1px solid #eee}
.card h3{margin-top:0}
.card .price{font-weight:700;margin:8px 0 12px}
.card-footer{margin-top:12px}
.cta{background:linear-gradient(180deg,#f8fafc,#fff);border-top:1px solid #eee}
.footer-grid{display:flex;justify-content:space-between;align-items:center;padding:24px 0}
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.disclaimer{font-size:0.85rem;color:var(--muted);margin-top:10px}
/* Responsive */
@media(max-width:900px){
  .hero-grid{grid-template-columns:1fr}
  .map-grid{grid-template-columns:1fr}
  .pricing-grid{grid-template-columns:1fr}
  .main-nav{display:none}
}
/* Tooltip basics for badges */
[data-tip]{position:relative}
[data-tip]:hover::after{content:attr(data-tip);position:absolute;left:50%;transform:translateX(-50%);bottom:calc(100% + 8px);background:rgba(15,23,42,0.95);color:#fff;padding:6px 8px;border-radius:6px;font-size:12px;white-space:nowrap}
/* Simple focus styles */
a:focus,button:focus,input:focus{outline:3px solid rgba(59,130,246,0.15);outline-offset:3px}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Basic interactive features: path map, rotating proof gallery, tooltips are CSS-based
  const form = document.getElementById('goals-form');
  const buildBtn = document.getElementById('build-path');
  const clearBtn = document.getElementById('clear-goals');
  const svg = document.getElementById('path-svg');
  const meterFill = document.querySelector('.meter-fill');
  const meterText = document.getElementById('meter-text');
  const miniTestimonial = document.getElementById('mini-testimonial');
  const badges = document.querySelectorAll('#badge-rotator .badge');

  // Testimonials rotation in the larger proof gallery
  const testimonials = Array.from(document.querySelectorAll('#testimonials .testimonial'));
  let testimonialIndex = 0;
  function rotateTestimonials(){
    testimonials.forEach((t,i)=>t.classList.toggle('active', i===testimonialIndex));
    testimonialIndex = (testimonialIndex + 1) % testimonials.length;
  }
  setInterval(rotateTestimonials,5000);
  rotateTestimonials();

  // mini badge rotator in hero
  let badgeIndex = 0;
  function rotateBadges(){
    badges.forEach((b,i)=>b.style.transform = `scale(${i===badgeIndex?1.05:0.95})`);
    badgeIndex = (badgeIndex + 1) % badges.length;
  }
  setInterval(rotateBadges,3500);
  rotateBadges();

  // Simple path generator for 30 days
  function generatePath(selectedGoals, selectedHabits){
    const days = 30;
    const points = [];
    // simple wave influenced by number of goals/habits
    const intensity = Math.min(3, Math.max(1, selectedGoals.length || 1)) + Math.min(2, selectedHabits.length || 0);
    for(let d=0; d<days; d++){
      const x = 20 + (d*(960/days));
      const y = 120 + Math.sin((d/30)*Math.PI*2*intensity)*40;
      points.push([x,y]);
    }
    return points;
  }

  // Render SVG path and milestone dots
  function renderPath(points){
    while(svg.firstChild) svg.removeChild(svg.firstChild);
    // polyline
    const ns = 'http://www.w3.org/2000/svg';
    const poly = document.createElementNS(ns,'polyline');
    poly.setAttribute('fill','none');
    poly.setAttribute('stroke','#7c3aed');
    poly.setAttribute('stroke-width','4');
    poly.setAttribute('stroke-linecap','round');
    poly.setAttribute('stroke-linejoin','round');
    poly.setAttribute('points', points.map(p=>p.join(',')).join(' '));
    poly.setAttribute('opacity','0.95');
    svg.appendChild(poly);

    // Milestones at days 7,14,21,30
    [6,13,20,29].forEach((idx,i)=>{
      const g = document.createElementNS(ns,'g');
      const [x,y] = points[idx];
      const circle = document.createElementNS(ns,'circle');
      circle.setAttribute('cx',x);
      circle.setAttribute('cy',y);
      circle.setAttribute('r',14 - i*2);
      circle.setAttribute('fill','#fff');
      circle.setAttribute('stroke','#2b6cb0');
      circle.setAttribute('stroke-width','3');
      g.appendChild(circle);
      const label = document.createElementNS(ns,'text');
      label.setAttribute('x',x);
      label.setAttribute('y',y+5);
      label.setAttribute('text-anchor','middle');
      label.setAttribute('font-size','12');
      label.setAttribute('fill','#0f172a');
      label.textContent = ['wk1','wk2','wk3','wk4'][i];
      g.appendChild(label);
      svg.appendChild(g);
    });
  }

  // Calculate readiness percentage based on selections
  function readinessPercent(goalsCount,habitsCount){
    const max = 5; // 5 signals full readiness
    const score = Math.min(max, goalsCount + Math.floor(habitsCount/1));
    return Math.round((score/max)*100);
  }

  function updateMeter(percent){
    meterFill.style.width = percent + '%';
    meterText.textContent = percent + '% ready';
    const meter = document.querySelector('.meter');
    meter.setAttribute('aria-valuenow', String(percent));
  }

  // Pull selected goals and habits
  function collectSelections(){
    const selectedGoals = Array.from(document.querySelectorAll('input[name="goal"]:checked')).map(i=>i.value);
    const selectedHabits = Array.from(document.querySelectorAll('#micro-list input[type="checkbox"]:checked')).map(i=>i.getAttribute('data-habit'));
    return {selectedGoals,selectedHabits};
  }

  buildBtn.addEventListener('click', ()=>{
    const {selectedGoals, selectedHabits} = collectSelections();
    const points = generatePath(selectedGoals, selectedHabits);
    renderPath(points);
    const pct = readinessPercent(selectedGoals.length, selectedHabits.length);
    updateMeter(pct);
    // update mini testimonial to reflect chosen goal (simple heuristic)
    const mini = {
      energy: '"I felt steadier energy within a week of the plan."',
      sleep: '"Improved timing for sleep with a small evening routine."',
      focus: '"The plan sharpened my most productive hours."',
      movement: '"Daily movement became easy to commit to."',
      stress: '"Clear tactics for calmer reactivity."'
    };
    if(selectedGoals.length) miniTestimonial.textContent = mini[selectedGoals[0]] || '"A practical, testable plan to start."';
    else miniTestimonial.textContent = '"Choose goals to shape a tailored path."';
  });

  clearBtn.addEventListener('click', ()=>{
    // reset inputs
    form.querySelectorAll('input[type="checkbox"]').forEach(cb=>cb.checked=false);
    // clear svg
    while(svg.firstChild) svg.removeChild(svg.firstChild);
    updateMeter(0);
    miniTestimonial.textContent = '"Choose goals to shape a tailored path."';
  });

  // Apply habits to the path (recalculate quickly)
  document.getElementById('apply-habits').addEventListener('click', ()=>{
    const {selectedGoals,selectedHabits} = collectSelections();
    const points = generatePath(selectedGoals, selectedHabits);
    renderPath(points);
    const pct = readinessPercent(selectedGoals.length, selectedHabits.length);
    updateMeter(pct);
  });

  // keyboard accessible testimonials switching
  document.addEventListener('keydown', (e)=>{
    if(e.key === 'ArrowRight') rotateTestimonials();
  });

  // initial demo render
  const initialPoints = generatePath([],[]);
  renderPath(initialPoints);
  updateMeter(0);
})();"} 
